import heapq

def func(lists,k):
    count = {}
    for lst in lists:
        for num in lst:
            if num in count:
                count[num] += 1
            else:
                count[num] = 1

    # Create a max-heap based on the frequency of each number
    max_heap = []
    for num, freq in count.items():
        heapq.heappush(max_heap, (-freq, num))

    result = []
    while max_heap and len(result) < k:
        _, num = heapq.heappop(max_heap)
        result.append(num)

    return result[::-1]
```

