def rearange_string(s):
    count = {}
    for char in s:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1

    odd_count = sum(1 for char, cnt in count.items() if cnt % 2 != 0)

    if odd_count > 1:
        return False

    sorted_chars = sorted(count.keys(), key=lambda x: count[x])
    result = []
    i = 0
    j = len(sorted_chars) - 1

    while i <= j:
        if i == j:
            result.append(sorted_chars[i])
        else:
            result.extend([sorted_chars[i], sorted_chars[j]])
        i += 1
        j -= 1

    return ''.join(result)
```

