def max_sum(arr, n):
    increasing = [1] * n
    decreasing = [1] * n

    # Build up the increasing sequence
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # Build down the decreasing sequence
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # Find the maximum sum of bi-tonic sub-sequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, increasing[i] + decreasing[i] - 1)

    return max_sum
```

